using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Fibers;

internal sealed class FiniteRectangleTransportDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Every finite rectangle menu on the positive five-mode fiber has an exact continuous transport realization.",
        H("Actual Finite Rectangle Transport"),
        Blocks(Describe.Lean(
            DescribeId.Create("finite-rectangles-realize"),
            DeclarationHandle.Create("D5/S3/Quantum/Fibers/FiniteRectangleTransport.finite_rectangles_realize"),
            H("Exact realization by finite continuous controls"),
            StatementSource.FromAuthor(Statement()),
            AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("The base b is the triple (X,Y,Z), with 0 < Z < 1 and 0 < X,Y < 1-Z. Its open fiber J(b) has endpoints max(0,X+Y-(1-Z)) and min(X,Y). The five probabilities, in the mode order (0,1,2,3,13), are (1-Z-X-Y+k,X-k,Z,Y-k,k). Their strict positivity and total one use the existing InteriorProbability carrier.")),
                Paragraph(Text("The direction is (1,-1,0,-1,1). The information coefficient is the sum of the four reciprocal bottom probabilities. The phase weight w is the direction divided coordinatewise by probability times information. Compatible(q(t)) asserts that the middle phase is zero and that the direction paired with the lifted phases equals the real relation phase. The state of a history q consists of the probability coordinate k, the real lifted relation phase c, and five real lifted phases v. They use the original negative phase convention psi(s)=sqrt(p(s))*exp(-i*v(s)). The instantaneous weighted phase velocity has zero probability mean, because the sum of p(s)*w(s) is zero. Duration(A) is four times the length of the finite menu A; its phase target is the sum of a times (w(k)-w(k0)) over the entries (k,a).")),
                Paragraph(Text("Admissible(b,N,q) requires continuity of the actual real-time function q, probability coordinates in J(b) on the closed interval from zero to N, finite variation of c, and an affine chart on each unit-time leg. On every open leg and for every mode, the probability derivative equals the direction times the derivative of k, and the derivative of v equals w(k) times the derivative of c. It also requires integrability of every actual transport component and equality of its integral with the corresponding terminal minus initial lifted phase. Thus the supplied object is a piecewise linear control with its transported state lift and exact integral residual.")),
                Paragraph(Text("For each menu entry, the four successive vertices change k from k0 to k, change c from zero to a at k, return k to k0, and return c to zero at k0. The phase changes on the two phase legs are a times w(k) and minus a times w(k0). Concatenating these vertices gives the real-time interpolation; matching endpoints prove continuity, and affine charts give finite variation and the differential law.")),
                Paragraph(Text("All real coefficients, including negative and zero coefficients, repeated heights, either symmetry wall, and the empty menu are included. There is no uniform speed, energy or amplitude bound. This declaration realizes every supplied finite representation. The application below constructs representations on every pole stratum and then identifies the exact compact group."))),
            DescribeRole.Theorem),
            Describe.Lean(
                DescribeId.Create("weight-compatible"),
                DeclarationHandle.Create("D5/S3/Quantum/Fibers/FiniteRectangleTransport.weight_compatible"),
                H("Middle gauge and unit relation charge"),
                StatementSource.FromAuthor(WeightStatement()),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("At each interior height, the middle phase weight vanishes and the direction paired with the phase weight equals one. Strict positivity of the four bottom probabilities makes the information coefficient nonzero. These identities govern the transported gauge and relation phase on every finite rectangle and also apply pointwise to general histories."))),
                DescribeRole.Theorem),
            Paragraph(Text("Let T be finite, let k be continuous on the interval between zero and T with values in the same open fiber, and let alpha be interval integrable. Put H(i) equal to the integral of w(k(t))(i) times alpha(t), and put q equal to the integral of alpha. Each component of w composed with k is continuous: the positive affine probabilities and their positive reciprocal sum keep every denominator nonzero. Multiplication of an integrable function by a continuous function on a compact interval therefore proves that every component defining H is integrable.")),
            Paragraph(Text("Define V(b) by zero middle component, zero direction charge, equality of components 0 and 13 when X+Y=1-Z, and equality of components 1 and 3 when X=Y. Integrating the middle and charge identities gives H(2)=0 and H(0)-H(1)-H(3)+H(13)=q. On either wall the relevant affine probabilities and signs coincide, so the corresponding weights, and then their integrals, coincide. Subtracting q times w(k0), whose charge is one, shows that H-q*w(k0) belongs to V(b). This argument includes both walls simultaneously and does not require a finite affine chart decomposition.")),
            Paragraph(Text("For an absolutely continuous real phase lift chi, alpha is its derivative. The interval fundamental theorem of calculus identifies q with chi(T)-chi(0). Thus winding m gives H-2*pi*m*w(k0) in V(b), and zero winding gives H in V(b). If the five state-phase coordinates are absolutely continuous and satisfy the transport derivative law almost everywhere, the same fundamental theorem identifies H with their terminal minus initial values. Finite variation alone cannot replace absolute continuity in this endpoint statement.")),
            Paragraph(Text("For a continuous phase that is C1 on finitely many consecutive subintervals, choose arbitrary nondecreasing partition times from zero to T. On each open subinterval its derivative agrees with a continuous rate on the closed subinterval. That rate is integrable; changing values at partition endpoints does not change the interval integral. The ordinary fundamental theorem on each subinterval and telescoping of the finite endpoint sum give q=chi(T)-chi(0). Hence the same upper inclusion applies to finite piecewise C1 controls as well, without imposing unit-time legs or affine motion.")),
            Paragraph(Text("When X=Y and X+Y=1-Z, the target equations give exactly h=(t,t,0,t,t), with t any real number. The weight is ((X-k)/(2X),-k/(2X),0,-k/(2X),(X-k)/(2X)). Fix k1=k0+(upper(b)-k0)/4 before selecting t. It is an interior height distinct from k0. The real coefficient a=-2*X*t/(k1-k0) makes a*(w(k1)-w(k0)) equal h. Applying finite_rectangles_realize to the actual singleton menu [(k1,a)] supplies a continuous four-leg transport with strict support, the original gauge, zero real winding, and terminal phase h. Negative and zero targets are included. In particular the double wall has a real line of reachable residuals, including nonzero residuals.")),
            Paragraph(Text("For the construction on every stratum, put r=1-Z and A=X+Y-r. The bottom poles, in the source labels (0,1,3,13), are (A,X,Y,0). On the strict base A<X, A<Y, X>0 and Y>0. Thus the only collisions are A=0 and X=Y. Retain representatives 0 and 1, also 3 when X differs from Y, and also 13 when A differs from zero. In Fin 5 the last source label is index 4. The representative map sends 3 to 1 on X=Y and 13 to 0 on A=0, and fixes every other bottom mode. This restores both the pole and the target component in each omitted coordinate. There are g=4-deltaMinus-deltaPlus representatives, where the two indicators record the respective walls.")),
            Paragraph(Text("Fix the base and k0 before choosing the target. Enumerate the representatives by indices j from zero to g-1 and set k(j)=k0+(j/4)*(upper(b)-k0), with real division. Index zero gives k0. Since 2 <= g <= 4 and k0 is strictly below upper(b), these heights are distinct and lie strictly inside the original fiber. Every bottom probability is positive at each height, the information coefficient I is positive, and k(j) differs from every pole. Products of height differences, pole differences, and cross differences are therefore nonzero on every stratum. No genericity assumption removes either wall.")),
            Paragraph(Text("Here are explicit interpolation coefficients. For this fixed height menu define Q(t) as the product of t-k(l) over all g indices, and D(j) as the product of k(j)-k(l) over all l different from j. Let P(h) be the Lagrange polynomial of degree less than g with values h(s)*Q(lambda(s)) at the representative poles lambda(s). Equivalently P(h)(t) is the sum over representative s of h(s)*Q(lambda(s)) times the product, over representatives v different from s, of (t-lambda(v))/(lambda(s)-lambda(v)). Define a(j)=-I(k(j))*P(h)(k(j))/D(j). These are real signed coefficients determined by the target, with all heights already fixed.")),
            Paragraph(Text("The exact pinned Lagrange.interpolate, eval_interpolate_at_node, degree_interpolate_lt, eq_interpolate and interpolate_eq_sum identities give the construction without a determinant assumption. Reconstruct P(h) at the height nodes, evaluate at each representative pole, and divide by Q(lambda(s)). This yields h(s)=sum_j a(j)*w(k(j))(s). The representative map extends the equality to all bottom modes; the middle equality uses h(2)=w(k(j))(2)=0. The minus sign in a(j) comes from replacing lambda(s)-k(j) by minus (k(j)-lambda(s)) after interpolation. The probability signs have already canceled in w(s)=1/(I*(k-lambda(s))); adding another mode sign would give a different construction.")),
            Paragraph(Text("Apply weight_compatible to the reconstructed five-coordinate vector. It gives sum_j a(j)=h(0)-h(1)-h(3)+h(13). For h in V(b) this sum is zero. Consequently the reference coefficient is minus the sum of the other coefficients, and h is exactly the sum over 1 <= j < g of a(j)*(w(k(j))-w(k0)). The actual list [(k(1),a(1)),...,(k(g-1),a(g-1))] has length g-1 and all its heights are in the strict fiber. Applying finite_rectangles_realize directly to this list gives terminal phase h, zero real winding, the middle-fixed gauge and strict probabilities throughout the path. This includes the general stratum, each single wall separately, their intersection, and all signs or zeros of the coefficients.")),
            Paragraph(Text("The dimension and the rectangle count have matching quantifiers. Restriction to the representative coordinates is a linear equivalence from U(b), the space imposing the middle and wall equations, to the real functions on g representatives. Its inverse copies each representative value to its pole group and assigns zero to the middle mode. Hence U(b) has dimension g. The charge functional on U(b) is onto because w(k0) belongs to U(b) and has charge one. Rank-nullity gives dim V(b)=g-1: three off both walls, two on either single wall, and one on their intersection. On a fixed menu of n heights, the rectangle residual map is a linear map from real n-space to V(b). Surjectivity requires n >= dim V(b). The selected g-1 auxiliary heights attain this bound, and their residual differences form a basis; their coefficients are unique. This lower bound concerns a fixed target-independent menu. Individual targets can require fewer nonzero coefficients.")),
            Paragraph(Text("The finite chart description also identifies an original admissible control. On each closed unit leg, the constructed k and chi agree with affine functions whose derivatives are constant continuous rates; the transported phases obey the stated derivative law on the open leg. The complete path is continuous. The sum of its finitely many leg variations is finite, by the variation formula for adjacent intervals and the Lipschitz bound for each affine chart. It is therefore a finite piecewise C1 control with finite phase variation in the original loop class. Applying the finite piecewise fundamental theorem to every phase coordinate and using the transport derivative equality on each open leg identifies the original integral residual with the actual terminal phase. The original class also contains arbitrary absolutely continuous controls; the general-history upper inclusion above applies to those controls without a finite-chart hypothesis.")),
            Paragraph(Text("For any integer m and any target h with h-2*pi*m*w(k0) in V(b), first synthesize that remainder. Prepend the unit-time fixed-height phase leg k=k0, chi=2*pi*m*t, theta=2*pi*m*t*w(k0). Follow it by the rectangle path with its relation phase translated by 2*pi*m and its lifted phases translated by 2*pi*m*w(k0). The values match at the join, translations preserve the differential law, and weight_compatible preserves the gauge and exact real relation charge at every time. The final probability coordinate is k0, the relation phase is 2*pi*m, and the final lifted phase is h. Every integer, including negative and zero winding, is included. The phase coordinate closes on its original circle; no state or ray return is asserted.")),
            Paragraph(Math(ReachabilityStatement())),
            Paragraph(Text("Here Reachable uses the original absolutely continuous or finite piecewise C1 control class with finite phase variation and the integral of w(k)*chi', and d(b)=3-deltaMinus-deltaPlus. The necessary inclusion and the explicit list construction prove both directions. The interpolation, dimension and integration tools are classical; their application gives no mathematical priority claim. The original source's geometric-control and Cauchy-determinant references supply context, not additional hypotheses or a transport realization certificate. There is no imposed uniform speed, energy, coefficient or amplitude bound.")),
            Paragraph(Text("For the exact compact holonomy of original Theorem 3.3, use the physical circle T=Real.Angle=R/(2*pi*Z), with its quotient topology and additive group structure. A compact phase is a function from Fin 5 to T, with index 4 denoting the original mode 13. Write [h] for componentwise reduction of a real five-vector h. Define K(b) as the subgroup of these compact phases satisfying phi(2)=0, phi(0)-phi(1)-phi(3)+phi(13)=0 in T, phi(0)=phi(13) on Eminus, and phi(1)=phi(3) on Eplus. Give K(b) the subspace topology of T^5. The reachable set is precisely K(b): the quantifiers are over an integer winding and an actual original control, followed by its integral residual and reduction [h]. This equality involves no topological closure.")),
            Paragraph(Text("The original base b=(X,Y,Z), strict support interval J(b), negative state-phase convention and middle-fixed gauge are the same as in the real construction above. The control class is the original union of absolutely continuous k and chi, or continuous finite piecewise C1 k and chi, with finite phase variation. The upper inclusion holds for both alternatives. The sufficiency witnesses are actual continuous paths with finitely many affine charts, so belong to the second alternative without adding a regularity premise to the target. For either class, the real all-sector equivalence becomes Reachable(b,k0,m,h) if and only if h belongs to U(b) and its real charge h(0)-h(1)-h(3)+h(13) is 2*pi*m. This follows by subtracting 2*pi*m*w(k0), using w(k0) in U(b) with unit charge, and invoking the same real all-sector construction. It is not an assumption that a vector of this charge is already reachable.")),
            Paragraph(Text("For a candidate phi in K(b), choose one real representative of each grouped phase, copy it to every member of its group, and set the middle representative to zero. For example, choose phi(0).toReal and phi(1).toReal, use phi(1).toReal also at mode 3 on Eplus, and phi(0).toReal also at mode 13 on Eminus; use the independent representatives at the other modes off their walls. This gives v in U(b) with [v]=phi. The circle-kernel equation says [charge(v)]=0. The exact circle quotient criterion gives charge(v)=2*pi*n for an integer n. Thus v-2*pi*n*w(k0) is in V(b). Apply the original all-sector construction to this remainder and prepend its signed fixed-height winding leg. The final integral residual is v, with compact phase phi. No real reachability, desired kernel membership of a control output, or component classification is a premise of this sufficiency argument.")),
            Paragraph(Text("The grouped coordinates and coefficient rows retain their actual source order. Off both walls the groups are (0),(1),(3),(13), with row (1,-1,-1,1). On Eminus alone the groups are (0,13),(1),(3), with row (2,-1,-1). On Eplus alone the groups are (0),(1,3),(13), with row (1,-2,1). On the double wall the groups are (0,13),(1,3), with row (2,-2). These four rows suffice here; no generic Smith normal form or orbit-closure theorem is needed.")),
            Paragraph(Text("Here are explicit additive homeomorphisms, with all entries in T and the middle entry shown. Off both walls, send phi to (phi(0),phi(1),phi(3)); its inverse sends (a,b,c) to (a,b,0,c,b+c-a). On Eminus alone, send phi to (phi(0),phi(1)); its inverse sends (a,b) to (a,b,0,2*a-b,a). On Eplus alone use the same selected coordinates, but the inverse is (a,b,0,b,2*b-a). The charge equation and the respective wall equalities prove both inverse identities. Coordinate projection, addition and subtraction are continuous, so each map and inverse is continuous in the stated subgroup topology. Hence K(b) is topologically additively equivalent to T^3 off the walls and to T^2 on either single wall, in each orientation.")),
            Paragraph(Text("On the double wall put t=phi(1) and d=phi(0)-phi(1). Its charge equation is 2*d=0. The pinned circle torsion criterion gives exactly d=0 or d=pi. Identify this two-point subgroup with ZMod 2 by the additive map rho([m])=[pi*m]. One construction first uses ZMod.toAddCircle into the unit-period circle, then the circle scaling equivalence from period one to period 2*pi. Its injectivity and the two-torsion criterion give a bijective additive map. Both finite two-point spaces have the discrete topology, so this map and its inverse are continuous. The double-wall equivalence is phi mapped to (t,rho inverse(d)), with inverse (t,e) mapped to (t+rho(e),t,0,t,t+rho(e)). This is a continuous additive equivalence K(b) with T times ZMod 2, rather than a set bijection or an additive equivalence without topology.")),
            Paragraph(Text("The real image is exact. Off both walls and on either single wall every point of K(b) has a zero-charge real lift: take real representatives of the selected torus coordinates and substitute them into the displayed inverse formulas. On the double wall a real zero-charge lift has equal positive and negative grouped components; its image therefore has d=0. Conversely every compact point with d=0 is the image of the real vector (t,t,0,t,t), using a real representative t of its common compact phase. Thus the image of V(b) is all of K(b) on the three connected strata and exactly the d=0 subspace on the double wall.")),
            Paragraph(Text("This subspace is the identity component inside K(b). The real additive circle is path connected, and finite products of it are connected. Transport of connected components through each additive homeomorphism gives the whole group in the first three strata. For the double-wall product, the product component theorem gives the circle component times the component of zero in ZMod 2. The latter is its singleton zero because the finite discrete group is totally disconnected. Pulling this product component back gives precisely d=0. Consequently range(h mapped to [h], h in V(b)) equals connectedComponent(0 in K(b)) as sets, with no closure of the real image substituted.")),
            Paragraph(Text("Each prescribed winding sector also has an explicit real lift. Write Q=2*pi*m, and choose real representatives a,b,c of the selected compact coordinates. Off both walls use (a,b,0,c,b+c-a+Q). On Eminus alone use (a,b,0,2*a-b-Q,a). On Eplus alone use (a,b,0,b,2*b-a+Q). These vectors belong to U(b), have charge Q, and reduce to the desired compact phase because [Q]=0. Thus every integer winding realizes every compact class on either single wall and off both walls; there is no residual discrete component on a single wall.")),
            Paragraph(Text("On the double wall the prescribed-sector condition is d=rho([m])=[pi*m]. If it holds, choose a real representative t of phi(1) and use v=(t+pi*m,t,0,t,t+pi*m). It is in U(b), has charge 2*pi*m, and reduces exactly to phi. Conversely any original control of winding m has a real residual in U(b) with this charge; the double-wall equalities force v(0)-v(1)=pi*m, so its compact component label is the residue of m in ZMod 2. Therefore the winding-m sector consists exactly of points whose second coordinate under the displayed double-wall equivalence is [m]. This statement quantifies over all integers, including negative winding and zero. A fixed-height circle has grouped difference pi and lands in the other component; its entire compact phase need not be an order-two element. Parity describes its component, not its order within the circle factor.")),
            Paragraph(Text("One can also keep an initially chosen grouped representative v with charge 2*pi*n and correct it to any allowed winding m using integer representative shifts. Off Eminus add 2*pi*(m-n) only in mode 0; this covers the general stratum and the Eplus-only row (1,-2,1). On Eminus alone add 2*pi*(n-m) only in mode 1, the negative group of row (2,-1,-1). On the double wall, n and m have equal residues modulo two exactly when m-n=2*l for an integer l; add 2*pi*l to both modes 0 and 13. Each correction belongs to U(b), changes the charge to 2*pi*m and has zero compact phase, so preserves [v]. There is no sign restriction on n, m or l. In every case the corrected vector minus 2*pi*m*w(k0) lies in the original V(b). Applying the actual all-sector lift gives a continuous finite-chart state path starting at (k0,0,0), ending at the same probability coordinate with real relation phase 2*pi*m and the corrected lifted residual, maintaining Compatible at every time. Its phase transport integral equals that terminal residual in every mode. Thus integer representative sufficiency is connected to the original controls and the original w(k0), including the middle-fixed gauge.")),
            Paragraph(Text("The group assertion concerns actual outputs as well as coordinates. Every original loop output is in K(b), and every point of K(b) is an original loop output by the preceding construction. K(b) is an additive subgroup of T^5; its addition and negation are the ambient ones. The equality with this subgroup supplies exact actual-control realizations of the sum and negative of any reachable compact phases. The associated phase operators are diagonal, hence commute. The classification therefore applies to the exact reachable abelian subgroup.")),
            Paragraph(Text("For the endpoint-multiplicity formula, count vanishing original probabilities at the closed endpoints lower(b) and upper(b). The middle probability remains Z>0. At the lower endpoint, only mode 13 vanishes when X+Y<1-Z, only mode 0 when X+Y>1-Z, and both when X+Y=1-Z. At the upper endpoint only mode 1 vanishes when X<Y, only mode 3 when X>Y, and both when X=Y. The other bottom probabilities are strictly positive by the strict mean hypotheses. Consequently nuMinus=1+indicator(Eminus), nuPlus=1+indicator(Eplus), and dim V(b)=g-1=5-nuMinus-nuPlus. The gcd of these two actual endpoint counts is two precisely on the double wall and one otherwise. The four displayed continuous additive equivalences can therefore be written uniformly as K(b) equivalent to T^(5-nuMinus-nuPlus) times ZMod(gcd(nuMinus,nuPlus)), where ZMod 1 is the trivial topological additive group.")),
            Paragraph(Text("The completion cone angles 2*pi/nuMinus and 2*pi/nuPlus belong to the original endpoint geometry in Theorem 2.13; the compact-group calculation does not prove those metric statements. The correspondence between rank, component count and endpoint multiplicities uses this specific four-pole sign pattern and its two permitted same-sign collisions. It is not asserted for general symplectic reductions. The circle quotient, finite torsion and connected-component tools are classical, and their displayed application here claims no priority. The exact reachability construction, rather than the geometric-control terminology or determinant references in the original section 3.13, supplies the control bridge. No uniform cost, energy, speed, phase amplitude or adaptive-menu minimum is claimed.")),
            Paragraph(Text("For the fixed-area application of original Theorem 3.5, retain an actual real control (k,chi) on a finite interval [0,T] at the same strict base b and with k(0)=k(T)=k0. Require the original alternative of absolutely continuous k and chi, or continuous finite piecewise C1 k and chi, and finite phase variation. Zero winding means the exact real equality chi(T)-chi(0)=0. Define A by the signed integral of k(t)*chi'(t), and h(i) by the integral of w(k(t))(i)*chi'(t). These definitions concern the actual history and its real lifts. The continuity of k and interval integrability of chi' make the area integrand integrable, just as they do for the transport components.")),
            Paragraph(Text("Pair a real vector with the fixed initial law by L(h)=sum_i p(k0)(i)*h(i). Pointwise the original affine law gives p(k0)(i)=p(k)(i)-(k-k0)*d(i). The instantaneous mean-zero identity sum_i p(k)(i)*w(k)(i)=0 and weight_compatible, which gives sum_i d(i)*w(k)(i)=1, therefore give L(w(k))=-(k-k0). Interval integral linearity for the five integrable components yields L(h)=-A+k0*(chi(T)-chi(0)). The fundamental theorem for the absolutely continuous alternative, or the finite-piecewise fundamental theorem for the other alternative, supplies that endpoint difference. Every original zero-winding loop consequently obeys L(h)=-A, including controls with no finite affine-chart description.")),
            Paragraph(Text("Restrict L to the actual V(b) characterized above. The vector u=(1,1,0,1,1) belongs to V(b) on every stratum: its middle entry and direction charge are zero and it obeys both possible wall equalities. Its L value is r=1-Z>0. Thus for every real c, (c/r)*u is in V(b) and has L value c; the restriction is surjective. In particular hA=-(A/r)*u is a point of the level L=-A for every real signed area A, including zero and either sign.")),
            Paragraph(Text("Let K be the kernel of this restricted linear map. The level L=-A is exactly hA+K: subtracting hA turns its equation into L(h-hA)=0, and adding a kernel vector preserves it. This is a nonempty affine subspace of V(b), with direction K. Rank-nullity, using the one-dimensional range and the previously established dimensions of V(b), gives dim K=dim V(b)-1. The affine level therefore has dimension two off both walls, one on either single wall separately, and zero on their intersection. At double symmetry V(b) consists of multiples of u, so the unique real fixed-area residual is -(A/r)*u.")),
            Paragraph(Text("The area level is also exactly the original reachable residual set with prescribed area. Necessity uses the general-control inclusion in V(b) and the integral identity. For sufficiency take any h in V(b) with L(h)=-A. The finite selected-height construction supplies an actual admissible zero-winding state lift with integral residual h. Apply the same identity to that very history: its integral area is A. This proves prescribed-area realization for every vector in the affine level, rather than merely membership of a candidate vector or the existence of a separately chosen area witness.")),
            Paragraph(Text("Common initial phases can be retained throughout this construction. Given any fixed real thetaInitial with thetaInitial(2)=0, translate every constructed state (k,chi,theta) to (k,chi+d paired with thetaInitial,theta+thetaInitial). Translation preserves continuity and the finite affine charts. Its derivatives, strict probabilities, phase variation and signed area agree with the original increments. It starts at (k0,d paired with thetaInitial,thetaInitial), keeps the middle gauge and exact real relation phase, and ends with phases thetaInitial+h. The same translation applies to both comparison rectangles below. No initial bottom phase has been fixed specially to obtain their interference contrast.")),
            Paragraph(Text("Area is retained as a real signed history integral. It is not defined on arbitrary compact phase representatives. Changing a real lift h to h+2*pi*z, for an integer five-vector z, changes the weighted expression by 2*pi*sum_i p(k0)(i)*z(i). Equality of compact phases alone consequently cannot define this real area pairing. The fixed-area dimension statements concern real affine levels, with exact real zero winding; reducing phases modulo 2*pi is a subsequent operation.")),
            Paragraph(Text("For original Proposition 3.6 take exactly X=1/5, Y=2/5, Z=1/5, k0=1/20, k1=1/10 and k2=3/20. The strict fiber is (0,1/5); neither wall holds. In the source order (0,1,2,3,13), with mode 13 represented by Fin 5 index 4, the original law gives p(k0)=(5,3,4,7,1)/20. Divide each signed reciprocal d(i)/p(k)(i) by I(k), the sum of the four positive bottom reciprocals. This gives w(k0)=(21,-35,0,-15,105)/176, w(k1)=(22,-66,0,-22,66)/176 and w(k2)=(15,-105,0,-21,35)/176. These are the weights of this same probability source.")),
            Paragraph(Text("Use the actual singleton menus [(k1,2)] and [(k2,1)] in finite_rectangles_realize. Each is a four-unit-time rectangle: move from k0 to its selected height at fixed relation phase, raise the real relation phase by its selected phase height, return to k0 at fixed phase, and lower the phase to its initial value at k0. On the probability legs k is affine between positive interior heights; on the phase legs it is constant. The complete paths have strict positive support by the supplier, including all leg junctions. They are continuous with finite piecewise C1 controls and finite phase variation.")),
            Paragraph(Text("The residuals of these actual rectangles are hFirst=2*(w(k1)-w(k0)) and hSecond=w(k2)-w(k0). Their actual signed integrals are 2*(k1-k0)=1/10 and k2-k0=1/10. The two probability legs contribute zero area; the outbound and return phase legs contribute a*k and -a*k0. Equivalently applying the general integral identity to either supplied rectangle gives this same area from its residual. Both return to k0 with zero real winding and preserve the middle-fixed gauge. Their residual difference is exactly hFirst-hSecond=(1,1,0,-1,-1)/22. Its direction charge is zero, and its initial-probability pairing is zero: modes 0 and 1 together have mass 2/5, as do modes 3 and 13.")),
            Paragraph(Text("For any of the common initial phases, the two actual endpoint amplitudes are sqrt(p(k0)(i))*exp(-i*(thetaInitial(i)+hFirst(i))) and the same expression with hSecond. In the complex inner product their common initial phases cancel componentwise, leaving sum_i p(k0)(i)*exp(i*(hFirst(i)-hSecond(i))). The middle contribution is 1/5. The positive and negative difference pairs contribute (2/5)*exp(i/22) and (2/5)*exp(-i/22), so the overlap is the real number 1/5+(4/5)*cos(1/22). Its squared modulus is exactly [1/5+(4/5)*cos(1/22)] squared. Since 0<1/22<pi/2, its cosine is positive; strict decrease of cosine between zero and pi also makes it less than one. The bracket, and then its squared modulus, are strictly between zero and one.")),
            Paragraph(Text("These endpoints are different rays in the actual complex projective space. Their middle amplitude is the same nonzero number, because the initial phases agree and both middle increments vanish. A scalar identifying their rays would therefore equal one. Equality at mode 0 would then require exp(i/22)=1, contradicting cos(1/22)<1. The overlap inequality gives the same distinction between normalized endpoint states. Thus equal real signed area does not determine the endpoint ray at this original generic positive base. The pair is distinct from the uniform-probability rectangle example of section 2.6.")),
            Paragraph(Text("These consequences reuse the original probability, transport, real reachability and projective carriers together with classical interval integration, rank-nullity and complex exponential identities. They concern exact mathematical controls and ideal endpoint amplitudes. They impose no speed, energy, duration optimization, amplitude budget or finite-shot discrimination claim, and do not extend the positive-support gauge to a missing middle mode. The fixed-area assertion is confined to real zero winding; arbitrary-winding double-wall summaries, tensor spectra, support limits, conditioning, variation estimates and the coherence-history quotient require their respective further hypotheses and conclusions.")))));

    private static Formula R => Seq(Mathbb, Grp(F.Id("R")));
    private static Formula Apply(Formula f, Formula x) => Seq(f, Open, x, Close);
    private static Formula Part(string name, Formula q, Formula t) => Call(name, Apply(q, t));

    private static Formula ReachabilityStatement()
    {
        Formula b = F.Id("b"), kzero = F.Id("kzero"), m = F.Id("m"), h = F.Id("h");
        Formula z = Seq(Mathbb, Grp(F.Id("Z")));
        Formula residual = Seq(h, Minus, D(2), Pi, Sp, m, Call("phaseWeight", b, kzero));
        return Disp(Seq(
            Forall, Sp, b, Colon, Operatorname, Grp(F.Id("Base")), Comma, Sp,
            Call("ValidBase", b), Rightarrow, Sp,
            Forall, Sp, kzero, InMacro, Call("J", b), Comma, Sp,
            Call("dim", Call("V", b)), Eq, Call("d", b), Land, Sp,
            Forall, Sp, m, InMacro, z, Comma, Sp,
            Forall, Sp, h, InMacro, Seq(R, Caret, Grp(D(5))), Comma, Sp,
            Call("Reachable", b, kzero, m, h), Leftrightarrow, Sp,
            residual, InMacro, Call("V", b)));
    }

    private static Formula WeightStatement()
    {
        Formula b = F.Id("b"), k = F.Id("k");
        Formula w = Call("phaseWeight", b, k);
        return Disp(Seq(
            Forall, Sp, b, Colon, Sp, Operatorname, Grp(F.Id("Base")), Comma, Sp,
            Call("ValidBase", b), Rightarrow, Sp,
            Forall, Sp, k, InMacro, Sp, Call("J", b), Comma, Sp,
            Apply(w, D(2)), Eq, D(0), Land, Sp,
            Apply(w, D(0)), Minus, Apply(w, D(1)), Minus,
            Apply(w, D(3)), Plus, Apply(w, D(4)), Eq, D(1)));
    }

    private static Formula Statement()
    {
        Formula b = F.Id("b"), e = F.Id("e"), menu = F.Id("A");
        Formula q = F.Id("q"), t = F.Id("t"), p = F.Id("p");
        Formula kzero = Seq(F.Id("k"), Underscore, Grp(D(0)));
        Formula duration = Call("Duration", menu);
        Formula interval = Call("J", b);
        Formula target = Call("residual", Call("phaseWeight", b), kzero, menu);
        return Disp(Seq(
            Begin, Grp(F.Id("gathered")),
            Forall, Sp, b, Colon, Sp, Operatorname, Grp(F.Id("Base")), Comma, Sp,
            Call("ValidBase", b), Rightarrow, RowBreak, Grp(),
            Forall, Sp, kzero, InMacro, Sp, interval, Comma, Sp,
            Forall, Sp, menu, Colon, Call("List", Seq(R, Caret, Grp(D(2)))), Comma, RowBreak, Grp(),
            Open, Forall, Sp, e, InMacro, Sp, menu, Comma, Sp,
            Call("fst", e), InMacro, Sp, interval, Close, Rightarrow, RowBreak, Grp(),
            Exists, Sp, q, Colon, Seq(R, To, Sp, Operatorname, Grp(F.Id("State"))), Comma, Sp,
            Call("Admissible", b, duration, q), Land, RowBreak, Grp(),
            Apply(q, D(0)), Eq, Open, kzero, Comma, D(0), Comma, D(0), Close, Land, RowBreak, Grp(),
            Part("kappa", q, duration), Eq, kzero, Land, Sp,
            Part("chi", q, duration), Eq, D(0), Land, RowBreak, Grp(),
            Open, Forall, Sp, t, InMacro, Sp, OpenBracket, D(0), Comma, duration, CloseBracket,
            Comma, Sp, Exists, Sp, p, Colon, Call("InteriorProbability", D(4)), Comma, Sp,
            Call("weight", p), Eq, Call("probability", b, Part("kappa", q, t)), Close,
            Land, RowBreak, Grp(),
            Open, Forall, Sp, t, InMacro, Sp, OpenBracket, D(0), Comma, duration, CloseBracket,
            Comma, Sp, Call("Compatible", Apply(q, t)), Close, Land, RowBreak, Grp(),
            Part("phase", q, duration), Eq, target,
            End, Grp(F.Id("gathered"))));
    }
}
